    fn assert_same_stat(actual: &WasmStat, expected: &WasmStat) {
        assert_eq!(actual.st_dev, expected.st_dev);
        assert_eq!(actual.st_ino, expected.st_ino);
        assert_eq!(actual.st_mode, expected.st_mode);
        assert_eq!(actual.st_nlink, expected.st_nlink);
        assert_eq!(actual.st_uid, expected.st_uid);
        assert_eq!(actual.st_gid, expected.st_gid);
        assert_eq!(actual.st_size, expected.st_size);
        assert_eq!(actual.st_atime_sec, expected.st_atime_sec);
        assert_eq!(actual.st_atime_nsec, expected.st_atime_nsec);
        assert_eq!(actual.st_mtime_sec, expected.st_mtime_sec);
        assert_eq!(actual.st_mtime_nsec, expected.st_mtime_nsec);
        assert_eq!(actual.st_ctime_sec, expected.st_ctime_sec);
        assert_eq!(actual.st_ctime_nsec, expected.st_ctime_nsec);
    }

    fn open_test_path(
        proc: &mut Process,
        host: &mut MockHostIO,
        path: &[u8],
        use_openat: bool,
    ) -> Result<i32, Errno> {
        if use_openat {
            sys_openat(proc, host, AT_FDCWD, path, O_RDWR, 0)
        } else {
            sys_open(proc, host, path, O_RDWR, 0)
        }
    }

    struct PtyFixture {
        _pty_table: std::sync::MutexGuard<'static, ()>,
        proc: Process,
        host: MockHostIO,
        pty_idx: usize,
        master_fd: i32,
        slave_fd: i32,
    }

    impl PtyFixture {
        fn new() -> Self {
            let pty_table = crate::pty::test_table_lock();
            let mut proc = Process::new(1);
            let pty_idx = crate::pty::alloc_pty(0, 0).expect("test PTY allocation");
            let pty = crate::pty::get_pty(pty_idx).expect("allocated test PTY");
            pty.locked = false;
            pty.master_refs = 1;
            pty.slave_refs = 1;
            pty.terminal.c_lflag &= !crate::terminal::ECHO;

            let master_ofd = proc.ofd_table.create(
                FileType::PtyMaster,
                O_RDWR,
                pty_idx as i64,
                b"/dev/ptmx".to_vec(),
            );
            let master_fd = proc
                .fd_table
                .alloc(crate::fd::OpenFileDescRef(master_ofd), 0)
                .unwrap();
            let slave_ofd = proc.ofd_table.create(
                FileType::PtySlave,
                O_RDWR,
                pty_idx as i64,
                format!("/dev/pts/{pty_idx}").into_bytes(),
            );
            let slave_fd = proc
                .fd_table
                .alloc(crate::fd::OpenFileDescRef(slave_ofd), 0)
                .unwrap();

            Self {
                _pty_table: pty_table,
                proc,
                host: MockHostIO::new(),
                pty_idx,
                master_fd,
                slave_fd,
            }
        }

        fn fd(&self, use_master: bool) -> i32 {
            if use_master {
                self.master_fd
            } else {
                self.slave_fd
            }
        }

        fn write_input(&mut self, data: &[u8]) {
            assert_eq!(
                sys_write(&mut self.proc, &mut self.host, self.master_fd, data),
                Ok(data.len()),
            );
        }

        fn write_output(&mut self, data: &[u8]) {
            assert_eq!(
                sys_write(&mut self.proc, &mut self.host, self.slave_fd, data),
                Ok(data.len()),
            );
        }

        fn read_slave(&mut self, len: usize) -> Result<Vec<u8>, Errno> {
            let mut bytes = vec![0; len];
            let n = sys_read(&mut self.proc, &mut self.host, self.slave_fd, &mut bytes)?;
            bytes.truncate(n);
            Ok(bytes)
        }

        fn read_master(&mut self, len: usize) -> Result<Vec<u8>, Errno> {
            let mut bytes = vec![0; len];
            let n = sys_read(&mut self.proc, &mut self.host, self.master_fd, &mut bytes)?;
            bytes.truncate(n);
            Ok(bytes)
        }

        fn custom_attrs(&mut self, fd: i32) -> [u8; crate::terminal::TERMIOS_SIZE] {
            let mut attrs = [0; crate::terminal::TERMIOS_SIZE];
            sys_tcgetattr(&mut self.proc, fd, &mut attrs).unwrap();
            attrs
        }

        fn ioctl_attrs(&mut self, fd: i32) -> [u8; crate::terminal::TERMIOS_SIZE] {
            let mut attrs = [0; crate::terminal::TERMIOS_SIZE];
            sys_ioctl(
                &mut self.proc,
                &mut self.host,
                fd,
                crate::terminal::TCGETS,
                &mut attrs,
            )
            .unwrap();
            attrs
        }

        fn set_custom_canonical(
            &mut self,
            fd: i32,
            canonical: bool,
            action: u32,
        ) -> Result<(), Errno> {
            let mut attrs = self.custom_attrs(fd);
            let mut lflag = u32::from_le_bytes(attrs[12..16].try_into().unwrap());
            if canonical {
                lflag |= crate::terminal::ICANON;
            } else {
                lflag &= !crate::terminal::ICANON;
            }
            attrs[12..16].copy_from_slice(&lflag.to_le_bytes());
            sys_tcsetattr(&mut self.proc, fd, action, &attrs)
        }

        fn set_ioctl_canonical(
            &mut self,
            fd: i32,
            canonical: bool,
            request: u32,
        ) -> Result<(), Errno> {
            let mut attrs = self.ioctl_attrs(fd);
            let mut lflag = u32::from_le_bytes(attrs[12..16].try_into().unwrap());
            if canonical {
                lflag |= crate::terminal::ICANON;
            } else {
                lflag &= !crate::terminal::ICANON;
            }
            attrs[12..16].copy_from_slice(&lflag.to_le_bytes());
            sys_ioctl(&mut self.proc, &mut self.host, fd, request, &mut attrs)
        }

        fn available(&mut self) -> i32 {
            let mut available = [0; 4];
            sys_ioctl(
                &mut self.proc,
                &mut self.host,
                self.slave_fd,
                0x541B,
                &mut available,
            )
            .unwrap();
            i32::from_le_bytes(available)
        }

        fn slave_revents(&mut self) -> i16 {
            let mut fds = [WasmPollFd {
                fd: self.slave_fd,
                events: POLLIN,
                revents: 0,
            }];
            sys_poll(&mut self.proc, &mut self.host, &mut fds, 0).unwrap();
            fds[0].revents
        }
    }

    impl Drop for PtyFixture {
        fn drop(&mut self) {
            crate::pty::free_pty(self.pty_idx);
        }
    }

    /// Mutex to serialize tests that access the global Unix socket registry.
    /// The registry uses UnsafeCell internally and is not thread-safe, so tests
    /// that call sys_bind/sys_connect for AF_UNIX must hold this lock.
    static UNIX_REGISTRY_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
    static FIFO_REGISTRY_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
    static THREAD_IDENTITY_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
    static SCM_RIGHTS_LIFETIME_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    #[test]
    fn rearm_host_interval_timer_rearms_the_host_with_remaining_time() {
        let mut host = MockHostIO::new();
        let mut proc = Process::new(70);

        // Disarmed: nothing to re-arm, no host call.
        assert_eq!(rearm_host_interval_timer(&proc, &mut host), Ok(false));
        assert_eq!(host.set_alarm_calls, Vec::<u32>::new());

        // Armed 2.5 s past the mock clock: re-armed rounded up, deadline
        // untouched.
        let now_ns = 1234567890u64 * 1_000_000_000 + 123456789;
        proc.alarm_deadline_ns = now_ns + 2_500_000_000;
        assert_eq!(rearm_host_interval_timer(&proc, &mut host), Ok(true));
        assert_eq!(host.set_alarm_calls, alloc::vec![3]);
        assert_eq!(proc.alarm_deadline_ns, now_ns + 2_500_000_000);

        // Expired while frozen: still owes its signal at the shortest host
        // alarm.
        proc.alarm_deadline_ns = now_ns - 1;
        assert_eq!(rearm_host_interval_timer(&proc, &mut host), Ok(true));
        assert_eq!(host.set_alarm_calls, alloc::vec![3, 1]);
    }

    #[test]
    fn process_borrow_paths_centralize_ambient_tid_fallback() {
        let direct_lookup = concat!("crate::process_table::", "current_tid()");
        let syscalls_source = include_str!("syscalls.rs");
        let signal_source = include_str!("signal.rs");

        // WHY: a syscall already holding &mut Process must not reborrow the
        // ProcessTable that owns it. The one test-only fallback is isolated in
        // current_tid_for_process; production dispatch uses the validated TID
        // mirrored into BlockingRetryState by ProcessTable::bind_current_tid.
        assert_eq!(syscalls_source.matches(direct_lookup).count(), 1);
        assert!(!signal_source.contains(direct_lookup));
    }

    #[test]
    fn socket_timeout_options_accept_time64_and_long64_numbers() {
        use wasm_posix_shared::socket::{
            AF_INET, IPPROTO_TCP, SOCK_STREAM, SOL_SOCKET, SO_RCVTIMEO, SO_RCVTIMEO_OLD,
            SO_SNDTIMEO, SO_SNDTIMEO_OLD,
        };

        assert_eq!(
            canonical_socket_timeout_optname(SOL_SOCKET, SO_RCVTIMEO),
            Some(SO_RCVTIMEO),
        );
        assert_eq!(
            canonical_socket_timeout_optname(SOL_SOCKET, SO_SNDTIMEO),
            Some(SO_SNDTIMEO),
        );
        assert_eq!(
            canonical_socket_timeout_optname(SOL_SOCKET, SO_RCVTIMEO_OLD),
            Some(SO_RCVTIMEO),
        );
        assert_eq!(
            canonical_socket_timeout_optname(SOL_SOCKET, SO_SNDTIMEO_OLD),
            Some(SO_SNDTIMEO),
        );
        assert_eq!(canonical_socket_timeout_optname(SOL_SOCKET, 19), None);
        assert_eq!(
            canonical_socket_timeout_optname(IPPROTO_TCP, SO_RCVTIMEO_OLD),
            None,
        );

        let mut proc = Process::new(9037);
        let mut host = MockHostIO::new();
        let fd = sys_socket(&mut proc, &mut host, AF_INET, SOCK_STREAM, 0).unwrap();
        let recv_opt = canonical_socket_timeout_optname(SOL_SOCKET, SO_RCVTIMEO_OLD).unwrap();
        let send_opt = canonical_socket_timeout_optname(SOL_SOCKET, SO_SNDTIMEO_OLD).unwrap();

        sys_setsockopt_timeout(&mut proc, fd, recv_opt, 1_250_000).unwrap();
        sys_setsockopt_timeout(&mut proc, fd, send_opt, 2_500_000).unwrap();

        assert_eq!(sys_getsockopt_timeout(&proc, fd, recv_opt), Ok(1_250_000));
        assert_eq!(sys_getsockopt_timeout(&proc, fd, send_opt), Ok(2_500_000));
    }

    fn test_unix_addr(path: &[u8]) -> Vec<u8> {
        let mut addr = vec![0; 2 + path.len() + 1];
        addr[0] = wasm_posix_shared::socket::AF_UNIX as u8;
        addr[2..2 + path.len()].copy_from_slice(path);
        addr
    }

    fn bind_test_unix_dgram(
        proc: &mut Process,
        host: &mut dyn HostIO,
        path: &[u8],
    ) -> (i32, Vec<u8>) {
        use wasm_posix_shared::socket::{AF_UNIX, SOCK_DGRAM};

        let fd = sys_socket(proc, host, AF_UNIX, SOCK_DGRAM, 0).unwrap();
        let addr = test_unix_addr(path);
        sys_bind(proc, host, fd, &addr).unwrap();
        (fd, addr)
    }

