    fn test_path_is_dir(path: &[u8]) -> bool {
        path.ends_with(b"/")
            || path.ends_with(b"dir")
            || matches!(
                path,
                b"/" | b"/absolute"
                    | b"/base"
                    | b"/base/dir/child"
                    | b"/bin"
                    | b"/data"
                    | b"/dev"
                    | b"/dst"
                    | b"/etc"
                    | b"/home"
                    | b"/home/user"
                    | b"/opt"
                    | b"/root"
                    | b"/some"
                    | b"/src"
                    | b"/srv"
                    | b"/test"
                    | b"/tmp"
                    | b"/usr"
                    | b"/usr/bin"
                    | b"/var"
                    | b"/wrong"
                    | b"/a"
                    | b"/a/b"
                    | b"/a/c"
            )
    }

    fn test_default_mode(path: &[u8]) -> u32 {
        if test_path_is_dir(path) {
            S_IFDIR | 0o755
        } else if path.starts_with(b"/bin/") || path.starts_with(b"/usr/bin/") {
            S_IFREG | 0o755
        } else {
            S_IFREG | 0o644
        }
    }

    fn test_stat_with_mode(mode: u32) -> WasmStat {
        WasmStat {
            st_dev: 0,
            st_ino: 1,
            st_mode: mode,
            st_nlink: 1,
            st_uid: 0,
            st_gid: 0,
            st_size: 1024,
            st_atime_sec: 0,
            st_atime_nsec: 0,
            st_mtime_sec: 0,
            st_mtime_nsec: 0,
            st_ctime_sec: 0,
            st_ctime_nsec: 0,
            _pad: 0,
        }
    }

    fn test_default_stat(path: &[u8]) -> WasmStat {
        test_stat_with_mode(test_default_mode(path))
    }

