    #[test]
    fn test_stat_resolves_relative_path() {
        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        proc.cwd = b"/home/user".to_vec();
        // Should not fail - relative paths get cwd prepended
        let stat = sys_stat(&mut proc, &mut host, b"file.txt").unwrap();
        assert_eq!(stat.st_mode & S_IFREG, S_IFREG);
    }

    /// VFS is the source of truth for file ownership. sys_stat must propagate
    /// uid/gid from the host VFS, not overwrite with the caller's effective
    /// IDs. The caller defaults to effective UID 0; with a host_stat returning
    /// (1000, 1000), any caller-identity override would clobber the result.
    #[test]
    fn test_sys_stat_returns_host_uid_gid() {
        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        host.set_file_with_owner(b"/foo", 1000, 1000, 0o644, b"hi");
        let st = sys_stat(&mut proc, &mut host, b"/foo").unwrap();
        assert_eq!(st.st_uid, 1000);
        assert_eq!(st.st_gid, 1000);
    }

    /// sys_lstat must also propagate honest uid/gid from the host VFS.
    #[test]
    fn test_sys_lstat_returns_host_uid_gid() {
        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        host.set_file_with_owner(b"/bar", 1001, 1002, 0o644, b"hi");
        let st = sys_lstat(&mut proc, &mut host, b"/bar").unwrap();
        assert_eq!(st.st_uid, 1001);
        assert_eq!(st.st_gid, 1002);
    }

    /// sys_fstat must propagate uid/gid from the host VFS for the underlying
    /// file (asymmetric uid/gid catches any single-field override).
    #[test]
    fn test_sys_fstat_returns_host_uid_gid() {
        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        host.set_file_with_owner(b"/qux", 1234, 5678, 0o644, b"hi");
        let fd = sys_open(&mut proc, &mut host, b"/qux", O_RDONLY, 0o644).unwrap();
        let st = sys_fstat(&mut proc, &mut host, fd).unwrap();
        assert_eq!(st.st_uid, 1234);
        assert_eq!(st.st_gid, 5678);
    }

    /// sys_fstatat (and therefore sys_statx, which delegates) must propagate
    /// uid/gid from the host VFS.
    #[test]
    fn test_sys_fstatat_returns_host_uid_gid() {
        use wasm_posix_shared::flags::AT_FDCWD;
        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        host.set_file_with_owner(b"/baz", 4242, 4343, 0o644, b"hi");
        let st = sys_fstatat(&mut proc, &mut host, AT_FDCWD, b"/baz", 0).unwrap();
        assert_eq!(st.st_uid, 4242);
        assert_eq!(st.st_gid, 4343);
    }

    /// sys_chown must propagate uid/gid into the host VFS so that a subsequent
    /// sys_stat returns the freshly written values. The asymmetric (uid != gid,
    /// neither equal to the caller's effective UID) pair catches any
    /// single-field clobber and any caller-identity override regression.
    #[test]
    fn test_sys_chown_round_trip_through_host() {
        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        // Seed the file with owner (0, 0) so the post-chown values are clearly
        // distinguishable from the initial state.
        host.set_file_with_owner(b"/foo", 0, 0, 0o644, b"hi");
        sys_chown(&mut proc, &mut host, b"/foo", 1000, 2000).unwrap();
        let st = sys_stat(&mut proc, &mut host, b"/foo").unwrap();
        assert_eq!(st.st_uid, 1000, "sys_chown uid did not reach host VFS");
        assert_eq!(st.st_gid, 2000, "sys_chown gid did not reach host VFS");
    }

    #[test]
    fn permission_prepare_chown_ids_enforces_the_authoritative_group_set() {
        let mut proc = Process::new(1);
        set_test_credentials(&mut proc, 1000, 1000, 2000, 3000, &[2000]);
        let st = WasmStat {
            st_dev: 0,
            st_ino: 1,
            st_mode: S_IFREG | 0o755,
            st_nlink: 1,
            st_uid: 1000,
            st_gid: 4000,
            st_size: 0,
            st_atime_sec: 0,
            st_atime_nsec: 0,
            st_mtime_sec: 0,
            st_mtime_nsec: 0,
            st_ctime_sec: 0,
            st_ctime_nsec: 0,
            _pad: 0,
        };

        assert_eq!(
            prepare_chown_ids(&proc, &st, CHOWN_ID_UNCHANGED, CHOWN_ID_UNCHANGED),
            Ok((1000, 4000)),
        );
        assert_eq!(
            prepare_chown_ids(&proc, &st, 1000, CHOWN_ID_UNCHANGED),
            Ok((1000, 4000)),
        );
        assert_eq!(
            prepare_chown_ids(&proc, &st, CHOWN_ID_UNCHANGED, 3000),
            Ok((1000, 3000)),
        );
        assert_eq!(
            prepare_chown_ids(&proc, &st, CHOWN_ID_UNCHANGED, 2000),
            Ok((1000, 2000)),
        );

        // An unprivileged owner cannot give a file away or name a group
        // outside the effective-plus-supplementary group set. POSIX requires
        // the unchanged sentinel to preserve an existing foreign group;
        // explicitly naming that group is not authorized.
        assert_eq!(
            prepare_chown_ids(&proc, &st, 1001, CHOWN_ID_UNCHANGED),
            Err(Errno::EPERM),
        );
        assert_eq!(
            prepare_chown_ids(&proc, &st, CHOWN_ID_UNCHANGED, 4000),
            Err(Errno::EPERM),
        );
        assert_eq!(
            prepare_chown_ids(&proc, &st, CHOWN_ID_UNCHANGED, 5000),
            Err(Errno::EPERM),
        );

        set_test_credentials(&mut proc, 1000, 1001, 2000, 3000, &[2000]);
        assert_eq!(
            prepare_chown_ids(&proc, &st, CHOWN_ID_UNCHANGED, CHOWN_ID_UNCHANGED),
            Err(Errno::EPERM),
        );

        set_test_credentials(&mut proc, 1000, 0, 2000, 3000, &[2000]);
        assert_eq!(prepare_chown_ids(&proc, &st, 5000, 6000), Ok((5000, 6000)),);
    }

    #[test]
    fn test_sys_chown_allows_owner_group_changes_but_rejects_foreign_ids() {
        let mut proc = Process::new(1);
        set_test_credentials(&mut proc, 1000, 1000, 2000, 1000, &[2000]);
        let mut host = MockHostIO::new();
        host.set_file_with_owner(b"/owned", 1000, 4000, 0o755, b"hi");

        sys_chown(&mut proc, &mut host, b"/owned", CHOWN_ID_UNCHANGED, 1000).unwrap();
        sys_chown(&mut proc, &mut host, b"/owned", 1000, 2000).unwrap();
        assert_eq!(
            sys_chown(&mut proc, &mut host, b"/owned", CHOWN_ID_UNCHANGED, 5000,),
            Err(Errno::EPERM),
        );
        assert_eq!(
            sys_chown(&mut proc, &mut host, b"/owned", 1001, CHOWN_ID_UNCHANGED,),
            Err(Errno::EPERM),
        );
        assert_eq!(
            host.chown_calls,
            vec![
                (b"/owned".to_vec(), 1000, 1000),
                (b"/owned".to_vec(), 1000, 2000),
            ],
        );
    }

    #[test]
    fn test_sys_chown_preserves_sentinels_and_delegates_same_ids() {
        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        host.set_file_with_owner(b"/owned", 1000, 2000, 0o644, b"hi");

        sys_chown(&mut proc, &mut host, b"/owned", CHOWN_ID_UNCHANGED, 3000).unwrap();
        sys_chown(&mut proc, &mut host, b"/owned", 4000, CHOWN_ID_UNCHANGED).unwrap();
        // An explicit request for the current IDs is not the (-1, -1)
        // sentinel case: it must still reach the backend for ctime, set-ID,
        // and filesystem error semantics.
        sys_chown(&mut proc, &mut host, b"/owned", 4000, 3000).unwrap();
        sys_chown(
            &mut proc,
            &mut host,
            b"/owned",
            CHOWN_ID_UNCHANGED,
            CHOWN_ID_UNCHANGED,
        )
        .unwrap();

        assert_eq!(
            host.chown_calls,
            vec![
                (b"/owned".to_vec(), 1000, 3000),
                (b"/owned".to_vec(), 4000, 3000),
                (b"/owned".to_vec(), 4000, 3000),
                (b"/owned".to_vec(), 4000, 3000),
            ],
        );
    }

