    // ---- MSG_OOB / SIOCATMARK tests ----

    #[test]
    fn test_send_recv_msg_oob() {
        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        use wasm_posix_shared::socket::*;

        let (fd0, fd1) = sys_socketpair(&mut proc, &mut host, AF_UNIX, SOCK_STREAM, 0).unwrap();

        // No OOB pending: SIOCATMARK returns 0
        let mut iobuf = [0u8; 4];
        sys_ioctl(&mut proc, &mut host, fd1, 0x8905, &mut iobuf).unwrap();
        assert_eq!(i32::from_le_bytes(iobuf), 0);

        // Send OOB byte from fd0
        let n = sys_send(&mut proc, &mut host, fd0, b"X", MSG_OOB).unwrap();
        assert_eq!(n, 1);

        // SIOCATMARK on fd1 returns 1
        let mut iobuf = [0u8; 4];
        sys_ioctl(&mut proc, &mut host, fd1, 0x8905, &mut iobuf).unwrap();
        assert_eq!(i32::from_le_bytes(iobuf), 1);

        // Recv OOB byte from fd1
        let mut buf = [0u8; 1];
        let n = sys_recv(&mut proc, &mut host, fd1, &mut buf, MSG_OOB).unwrap();
        assert_eq!(n, 1);
        assert_eq!(buf[0], b'X');

        // After reading OOB, SIOCATMARK returns 0
        let mut iobuf = [0u8; 4];
        sys_ioctl(&mut proc, &mut host, fd1, 0x8905, &mut iobuf).unwrap();
        assert_eq!(i32::from_le_bytes(iobuf), 0);
    }

    #[test]
    fn test_recv_msg_oob_no_data() {
        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        use wasm_posix_shared::socket::*;

        let (_fd0, fd1) = sys_socketpair(&mut proc, &mut host, AF_UNIX, SOCK_STREAM, 0).unwrap();

        // Recv OOB with no OOB pending returns EINVAL
        let mut buf = [0u8; 1];
        let err = sys_recv(&mut proc, &mut host, fd1, &mut buf, MSG_OOB).unwrap_err();
        assert_eq!(err, Errno::EINVAL);
    }

    #[test]
    fn test_send_msg_oob_closed_peer_cannot_target_reused_socket_slot() {
        let mut proc = Process::new(9040);
        let mut host = MockHostIO::new();
        use wasm_posix_shared::socket::*;

        let (sender_fd, peer_fd) =
            sys_socketpair(&mut proc, &mut host, AF_UNIX, SOCK_STREAM, 0).unwrap();
        let peer_entry = proc.fd_table.get(peer_fd).unwrap();
        let peer_ofd = proc.ofd_table.get(peer_entry.ofd_ref.0).unwrap();
        let peer_idx = (-(peer_ofd.host_handle + 1)) as usize;
        sys_close(&mut proc, &mut host, peer_fd).unwrap();

        let replacement_fd = sys_socket(&mut proc, &mut host, AF_UNIX, SOCK_STREAM, 0).unwrap();
        let replacement_entry = proc.fd_table.get(replacement_fd).unwrap();
        let replacement_ofd = proc.ofd_table.get(replacement_entry.ofd_ref.0).unwrap();
        let replacement_idx = (-(replacement_ofd.host_handle + 1)) as usize;
        assert_eq!(replacement_idx, peer_idx);

        assert_eq!(
            sys_send(&mut proc, &mut host, sender_fd, b"X", MSG_OOB).unwrap_err(),
            Errno::EPIPE,
        );
        assert!(proc.signals.is_pending(wasm_posix_shared::signal::SIGPIPE));
        assert!(proc
            .sockets
            .get(replacement_idx)
            .unwrap()
            .oob_byte
            .is_none());
    }

