        let mut host = MockHostIO::new();
        let (read_fd, write_fd) = sys_pipe(&mut proc).unwrap();
        sys_fcntl(&mut proc, read_fd, F_SETFL, O_NONBLOCK).unwrap();
        // Close write end
        sys_close(&mut proc, &mut host, write_fd).unwrap();
        // Read — should get 0 (EOF), not EAGAIN
