        // Verify O_NONBLOCK is set — read empty pipe should return EAGAIN
        let mut buf = [0u8; 16];
        let result = sys_read(&mut proc, &mut host, r, &mut buf);
        assert_eq!(result, Err(Errno::EAGAIN));
