        assert_eq!(
            sys_copy_file_range(&mut proc, &mut host, source, None, output, None, 2),
            Ok(1),
        );
        assert_eq!(sys_lseek(&mut proc, &mut host, source, 0, SEEK_CUR), Ok(1),);
        assert_eq!(host.append_mutations, vec![b"a".to_vec()]);
