    #[test]
    fn test_unix_stream_connect_same_process() {
        let _lock = UNIX_REGISTRY_LOCK.lock().unwrap();
        let mut proc = Process::new(9001);
        let mut host = MockHostIO::new();
        let path = b"/tmp/connect_9001.sock";
        // Clean up any stale registration from a prior test run
        let resolved = crate::path::resolve_path(path, &proc.cwd);
        unsafe { crate::unix_socket::global_unix_socket_registry() }.unregister(&resolved);

        // Create and bind a listener
        let server_fd = sys_socket(&mut proc, &mut host, 1, 1, 0).unwrap(); // AF_UNIX, SOCK_STREAM
        let mut addr = [
            0u8;
            wasm_posix_shared::kernel_scratch_wire::SOCKADDR_UNIX_BYTES as usize
        ];
        addr[0] = 1; // AF_UNIX
        addr[2..2 + path.len()].copy_from_slice(path);
        let addrlen = 2 + path.len() + 1;
        sys_bind(&mut proc, &mut host, server_fd, &addr[..addrlen]).unwrap();
        sys_listen(&mut proc, &mut host, server_fd, 5).unwrap();

        // Connect a client
        let client_fd = sys_socket(&mut proc, &mut host, 1, 1, 0).unwrap();
        sys_connect(&mut proc, &mut host, client_fd, &addr[..addrlen]).unwrap();

        // Client should be connected
        let entry = proc.fd_table.get(client_fd).unwrap();
        let ofd = proc.ofd_table.get(entry.ofd_ref.0).unwrap();
        let sock_idx = (-(ofd.host_handle + 1)) as usize;
        let sock = proc.sockets.get(sock_idx).unwrap();
        assert_eq!(sock.state, crate::socket::SocketState::Connected);

        // Server should have a pending connection
        let accepted_fd = sys_accept(&mut proc, &mut host, server_fd).unwrap();
        assert!(accepted_fd >= 0);

        // Lazily materializing the accepted socket must restore process-local
        // peer identity when the client and acceptor are still the same
        // process, so MSG_OOB retains its existing semantics.
        sys_send(
            &mut proc,
            &mut host,
            client_fd,
            b"X",
            wasm_posix_shared::socket::MSG_OOB,
        )
        .unwrap();
        let mut oob = [0u8; 1];
        assert_eq!(
            sys_recv(
                &mut proc,
                &mut host,
                accepted_fd,
                &mut oob,
                wasm_posix_shared::socket::MSG_OOB,
            )
            .unwrap(),
            1,
        );
        assert_eq!(oob, [b'X']);

        // Clean up
        unsafe { crate::unix_socket::global_unix_socket_registry() }.unregister(&resolved);
    }

    #[test]
    fn test_fork_child_accepts_parent_unix_listener_queue() {
        let _lock = UNIX_REGISTRY_LOCK.lock().unwrap();
        use crate::process_table::ProcessTable;

        const PARENT: u32 = 100;
        const CHILD: u32 = 101;
        let path = b"/tmp/fork_accept_9031.sock";
        let resolved = crate::path::resolve_path(path, b"/");
        unsafe { crate::unix_socket::global_unix_socket_registry() }.unregister(&resolved);

        let mut host = MockHostIO::new();
        let mut table = ProcessTable::new();
        assert_eq!(table.create_process().unwrap(), PARENT);
        let server_fd = sys_socket(table.get_mut(PARENT).unwrap(), &mut host, 1, 1, 0).unwrap();
        let mut addr = [
            0u8;
            wasm_posix_shared::kernel_scratch_wire::SOCKADDR_UNIX_BYTES as usize
        ];
        addr[0] = 1;
        addr[2..2 + path.len()].copy_from_slice(path);
        let addrlen = 2 + path.len() + 1;
        sys_bind(
            table.get_mut(PARENT).unwrap(),
            &mut host,
            server_fd,
            &addr[..addrlen],
        )
        .unwrap();
        sys_listen(table.get_mut(PARENT).unwrap(), &mut host, server_fd, 5).unwrap();

        assert_eq!(
            table.fork_process_for_caller(PARENT, PARENT).unwrap(),
            CHILD
        );

        let client_fd = {
            let parent = table.get_mut(PARENT).unwrap();
            let fd = sys_socket(parent, &mut host, 1, 1, 0).unwrap();
            sys_connect(parent, &mut host, fd, &addr[..addrlen]).unwrap();
            fd
        };
        let accepted_fd = {
            let child = table.get_mut(CHILD).unwrap();
            sys_accept(child, &mut host, server_fd).unwrap()
        };

        assert_eq!(
            sys_send(
                table.get_mut(PARENT).unwrap(),
                &mut host,
                client_fd,
                b"shared queue",
                0,
            )
            .unwrap(),
            12,
        );
        let mut buf = [0u8; 16];
        let received = sys_recv(
            table.get_mut(CHILD).unwrap(),
            &mut host,
            accepted_fd,
            &mut buf,
            0,
        )
        .unwrap();
        assert_eq!(&buf[..received], b"shared queue");

        {
            let child = table.get_mut(CHILD).unwrap();
            sys_close(child, &mut host, accepted_fd).unwrap();
            sys_close(child, &mut host, server_fd).unwrap();
        }
        {
            let parent = table.get_mut(PARENT).unwrap();
            sys_close(parent, &mut host, client_fd).unwrap();
            sys_close(parent, &mut host, server_fd).unwrap();
        }
        unsafe { crate::unix_socket::global_unix_socket_registry() }.unregister(&resolved);
    }

    #[test]
    fn test_unix_stream_connect_pushes_accept_wakeup() {
        let _lock = UNIX_REGISTRY_LOCK.lock().unwrap();
        let mut proc = Process::new(9012);
        let mut host = MockHostIO::new();
        let path = b"/tmp/wakeup_9012.sock";
        let resolved = crate::path::resolve_path(path, &proc.cwd);
        unsafe { crate::unix_socket::global_unix_socket_registry() }.unregister(&resolved);

        let server_fd = sys_socket(&mut proc, &mut host, 1, 1, 0).unwrap();
        let mut addr = [
            0u8;
            wasm_posix_shared::kernel_scratch_wire::SOCKADDR_UNIX_BYTES as usize
        ];
        addr[0] = 1; // AF_UNIX
        addr[2..2 + path.len()].copy_from_slice(path);
        let addrlen = 2 + path.len() + 1;
        sys_bind(&mut proc, &mut host, server_fd, &addr[..addrlen]).unwrap();
        sys_listen(&mut proc, &mut host, server_fd, 5).unwrap();

        let accept_idx = {
            let entry = proc.fd_table.get(server_fd).unwrap();
            let ofd = proc.ofd_table.get(entry.ofd_ref.0).unwrap();
            let sock_idx = (-(ofd.host_handle + 1)) as usize;
            proc.sockets.get(sock_idx).unwrap().accept_wake_idx.unwrap()
        };

        let mut wake_buf = [0u8; 16];
        crate::wakeup::drain(&mut wake_buf, 8);

        let client_fd = sys_socket(&mut proc, &mut host, 1, 1, 0).unwrap();
        sys_connect(&mut proc, &mut host, client_fd, &addr[..addrlen]).unwrap();

        let count = crate::wakeup::drain(&mut wake_buf, 8);
        unsafe { crate::unix_socket::global_unix_socket_registry() }.unregister(&resolved);

        assert_eq!(count, 1);
        assert_eq!(
            u32::from_le_bytes([wake_buf[0], wake_buf[1], wake_buf[2], wake_buf[3]]),
            accept_idx
        );
        assert_eq!(wake_buf[4], crate::wakeup::WAKE_ACCEPT);
    }

    #[test]
    fn test_accept_leaves_the_connection_for_the_host_named_winner() {
        let _lock = UNIX_REGISTRY_LOCK.lock().unwrap();
        let mut proc = Process::new(9013);
        let mut host = MockHostIO::new();
        let path = b"/tmp/select_9013.sock";
        let resolved = crate::path::resolve_path(path, &proc.cwd);
        unsafe { crate::unix_socket::global_unix_socket_registry() }.unregister(&resolved);

        let server_fd = sys_socket(&mut proc, &mut host, 1, 1, 0).unwrap();
        let mut addr = [
            0u8;
            wasm_posix_shared::kernel_scratch_wire::SOCKADDR_UNIX_BYTES as usize
        ];
        addr[0] = 1; // AF_UNIX
        addr[2..2 + path.len()].copy_from_slice(path);
        let addrlen = 2 + path.len() + 1;
        sys_bind(&mut proc, &mut host, server_fd, &addr[..addrlen]).unwrap();
        sys_listen(&mut proc, &mut host, server_fd, 5).unwrap();

        let accept_idx = {
            let entry = proc.fd_table.get(server_fd).unwrap();
            let ofd = proc.ofd_table.get(entry.ofd_ref.0).unwrap();
            let sock_idx = (-(ofd.host_handle + 1)) as usize;
            proc.sockets.get(sock_idx).unwrap().accept_wake_idx.unwrap()
        };

        let client_fd = sys_socket(&mut proc, &mut host, 1, 1, 0).unwrap();
        sys_connect(&mut proc, &mut host, client_fd, &addr[..addrlen]).unwrap();

        // A worker the host did not name gets EAGAIN and leaves the pending
        // connection queued, so the worker the host did name still finds it.
        host.accept_winner = Some(7777);
        assert_eq!(
            sys_accept(&mut proc, &mut host, server_fd).unwrap_err(),
            Errno::EAGAIN
        );
        host.accept_winner = Some(9013);
        let accepted_fd = sys_accept(&mut proc, &mut host, server_fd).unwrap();

        assert_eq!(host.accept_select_calls, vec![
            (accept_idx, 9013),
            (accept_idx, 9013),
        ]);

        sys_close(&mut proc, &mut host, accepted_fd).unwrap();
        sys_close(&mut proc, &mut host, client_fd).unwrap();
        sys_close(&mut proc, &mut host, server_fd).unwrap();
        unsafe { crate::unix_socket::global_unix_socket_registry() }.unregister(&resolved);
    }

    #[test]
    fn test_accept_does_not_ask_the_host_about_an_empty_queue() {
        let _lock = UNIX_REGISTRY_LOCK.lock().unwrap();
        let mut proc = Process::new(9014);
        let mut host = MockHostIO::new();
        let path = b"/tmp/select_9014.sock";
        let resolved = crate::path::resolve_path(path, &proc.cwd);
        unsafe { crate::unix_socket::global_unix_socket_registry() }.unregister(&resolved);

        let server_fd = sys_socket(&mut proc, &mut host, 1, 1, 0).unwrap();
        let mut addr = [
            0u8;
            wasm_posix_shared::kernel_scratch_wire::SOCKADDR_UNIX_BYTES as usize
        ];
        addr[0] = 1; // AF_UNIX
        addr[2..2 + path.len()].copy_from_slice(path);
        let addrlen = 2 + path.len() + 1;
        sys_bind(&mut proc, &mut host, server_fd, &addr[..addrlen]).unwrap();
        sys_listen(&mut proc, &mut host, server_fd, 5).unwrap();

        // Nothing is waiting, so there is no selection to spend: a replaying
        // host must not lose a recorded winner to a worker's idle poll.
        assert_eq!(
            sys_accept(&mut proc, &mut host, server_fd).unwrap_err(),
            Errno::EAGAIN
        );
        assert!(host.accept_select_calls.is_empty());

        sys_close(&mut proc, &mut host, server_fd).unwrap();
        unsafe { crate::unix_socket::global_unix_socket_registry() }.unregister(&resolved);
    }

