    #[test]
    fn munmap_of_fb_region_clears_binding_and_unbinds_host() {
        use core::sync::atomic::Ordering;
        use wasm_posix_shared::flags::O_RDWR;
        use wasm_posix_shared::mmap::{MAP_SHARED, PROT_READ, PROT_WRITE};
        crate::process_table::FB0_OWNER.store(-1, Ordering::SeqCst);

        let mut proc = Process::new(1);
        let mut host = TrackingHostIO::new();
        let fd = sys_open(&mut proc, &mut host, b"/dev/fb0", O_RDWR, 0).unwrap();
        let len = (640 * 400 * 4) as usize;
        let addr = sys_mmap(
            &mut proc,
            &mut host,
            0,
            len,
            PROT_READ | PROT_WRITE,
            MAP_SHARED,
            fd,
            0,
        )
        .unwrap();
        sys_munmap(&mut proc, &mut host, addr, len).unwrap();
        assert!(proc.fb_binding.is_none());
        assert_eq!(host.unbind_framebuffer_calls, alloc::vec![proc.pid as i32]);

        // Closing the fd then releases ownership (no binding remains).
        sys_close(&mut proc, &mut host, fd).unwrap();
        assert_eq!(crate::process_table::FB0_OWNER.load(Ordering::SeqCst), -1);
    }

    #[test]
    fn exec_commit_unbinds_fb_mapping_but_keeps_open_fd_owner() {
        use core::sync::atomic::Ordering;
        use wasm_posix_shared::flags::O_RDWR;
        use wasm_posix_shared::mmap::{MAP_SHARED, PROT_READ, PROT_WRITE};
        crate::process_table::FB0_OWNER.store(-1, Ordering::SeqCst);

        let mut proc = Process::new(1);
        let mut host = TrackingHostIO::new();
        let fd = sys_open(&mut proc, &mut host, b"/dev/fb0", O_RDWR, 0).unwrap();
        let len = (640 * 400 * 4) as usize;
        let _ = sys_mmap(
            &mut proc,
            &mut host,
            0,
            len,
            PROT_READ | PROT_WRITE,
            MAP_SHARED,
            fd,
            0,
        )
        .unwrap();
        commit_exec_state(&mut proc, &mut host, 0).unwrap();
        assert!(proc.fb_binding.is_none());
        assert_eq!(host.unbind_framebuffer_calls, alloc::vec![proc.pid as i32]);
        assert_eq!(
            crate::process_table::FB0_OWNER.load(Ordering::SeqCst),
            proc.pid as i32
        );
        sys_close(&mut proc, &mut host, fd).unwrap();
        assert_eq!(crate::process_table::FB0_OWNER.load(Ordering::SeqCst), -1);
    }

    #[test]
    fn open_dev_fb0_is_single_owner() {
        use core::sync::atomic::Ordering;
        crate::process_table::FB0_OWNER.store(-1, Ordering::SeqCst);

        let mut proc1 = Process::new(1);
        let mut proc2 = Process::new(2);
        let mut host = MockHostIO::new();

        // First open from pid 1 succeeds.
        let fd1 = sys_open(&mut proc1, &mut host, b"/dev/fb0", O_RDWR, 0).unwrap();

        // Second open from a different process is EBUSY.
        let err = sys_open(&mut proc2, &mut host, b"/dev/fb0", O_RDWR, 0).unwrap_err();
        assert_eq!(err, Errno::EBUSY);

        // Re-open by the SAME process is allowed.
        let fd1b = sys_open(&mut proc1, &mut host, b"/dev/fb0", O_RDWR, 0).unwrap();
        assert_ne!(fd1, fd1b);

        // After both fds in the owning process close, ownership releases.
        sys_close(&mut proc1, &mut host, fd1).unwrap();
        assert_eq!(
            crate::process_table::FB0_OWNER.load(Ordering::SeqCst),
            proc1.pid as i32
        );
        sys_close(&mut proc1, &mut host, fd1b).unwrap();
        assert_eq!(crate::process_table::FB0_OWNER.load(Ordering::SeqCst), -1);

        // Now another process can open.
        let fd2 = sys_open(&mut proc2, &mut host, b"/dev/fb0", O_RDWR, 0).unwrap();
        sys_close(&mut proc2, &mut host, fd2).unwrap();
        assert_eq!(crate::process_table::FB0_OWNER.load(Ordering::SeqCst), -1);
    }

    // -----------------------------------------------------------------
    // /dev/input/mice tests — mirror the fb0 surface.
    // -----------------------------------------------------------------

    /// Serializes tests that touch MICE_OWNER + the global mouse queue.
    /// Both pieces of state are process-global, so concurrent tests would
    /// interfere. Same pattern as `FB0_OWNER_LOCK` above.
    static MICE_OWNER_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    fn reset_mice_state() {
        use core::sync::atomic::Ordering;
        crate::mouse::MICE_OWNER.store(-1, Ordering::SeqCst);
        crate::mouse::reset();
    }

    #[test]
    fn match_virtual_device_recognizes_mice() {
        assert_eq!(
            match_virtual_device(b"/dev/input/mice"),
            Some(VirtualDevice::Mice)
        );
        // No /dev/input/event0 — evdev is out of scope for v1.
        assert_eq!(match_virtual_device(b"/dev/input/event0"), None);
    }

    #[test]
    fn mice_stat_is_chr() {
        let st = virtual_device_stat(VirtualDevice::Mice, 0, 0);
        assert_eq!(
            st.st_mode & wasm_posix_shared::mode::S_IFMT,
            wasm_posix_shared::mode::S_IFCHR
        );
        assert_eq!(st.st_ino, VirtualDevice::Mice.ino());
    }

    #[test]
    fn open_mice_acquires_ownership_and_second_open_from_other_pid_is_ebusy() {
        use core::sync::atomic::Ordering;
        let _g = MICE_OWNER_LOCK.lock().unwrap();
        reset_mice_state();

        let mut proc1 = Process::new(1);
        let mut proc2 = Process::new(2);
        let mut host = MockHostIO::new();

        let fd1 = sys_open(&mut proc1, &mut host, b"/dev/input/mice", O_RDONLY, 0).unwrap();
        assert_eq!(
            crate::mouse::MICE_OWNER.load(Ordering::SeqCst),
            proc1.pid as i32
        );

        let err = sys_open(&mut proc2, &mut host, b"/dev/input/mice", O_RDONLY, 0).unwrap_err();
        assert_eq!(err, Errno::EBUSY);

        // Re-open by the SAME process is allowed.
        let fd1b = sys_open(&mut proc1, &mut host, b"/dev/input/mice", O_RDONLY, 0).unwrap();
        assert_ne!(fd1, fd1b);
        sys_close(&mut proc1, &mut host, fd1).unwrap();
        sys_close(&mut proc1, &mut host, fd1b).unwrap();
    }

    #[test]
    fn read_mice_drains_injected_packets() {
        let _g = MICE_OWNER_LOCK.lock().unwrap();
        reset_mice_state();

        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        let fd = sys_open(&mut proc, &mut host, b"/dev/input/mice", O_RDONLY, 0).unwrap();

        crate::mouse::inject_event(7, -3, 0b001);

        let mut buf = [0u8; 3];
        let n = sys_read(&mut proc, &mut host, fd, &mut buf).unwrap();
        assert_eq!(n, 3);
        assert_eq!(buf[1] as i8, 7);
        assert_eq!(buf[2] as i8, -3);
        // bit3 (frame sync) + left button (bit0) + dy negative (bit5)
        assert_eq!(buf[0], 0x08 | 0x01 | 0x20);

        sys_close(&mut proc, &mut host, fd).unwrap();
    }

    #[test]
    fn read_mice_returns_eagain_when_empty() {
        let _g = MICE_OWNER_LOCK.lock().unwrap();
        reset_mice_state();

        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        let fd = sys_open(&mut proc, &mut host, b"/dev/input/mice", O_RDONLY, 0).unwrap();

        let mut buf = [0u8; 3];
        let err = sys_read(&mut proc, &mut host, fd, &mut buf).unwrap_err();
        assert_eq!(err, Errno::EAGAIN);

        sys_close(&mut proc, &mut host, fd).unwrap();
    }

    #[test]
    fn close_mice_releases_owner() {
        use core::sync::atomic::Ordering;
        let _g = MICE_OWNER_LOCK.lock().unwrap();
        reset_mice_state();

        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        let fd = sys_open(&mut proc, &mut host, b"/dev/input/mice", O_RDONLY, 0).unwrap();
        assert_eq!(
            crate::mouse::MICE_OWNER.load(Ordering::SeqCst),
            proc.pid as i32
        );

        // Buffered packet should be discarded on close.
        crate::mouse::inject_event(1, 1, 0);
        sys_close(&mut proc, &mut host, fd).unwrap();
        assert_eq!(crate::mouse::MICE_OWNER.load(Ordering::SeqCst), -1);
        assert!(
            !crate::mouse::has_data(),
            "close should reset the queue when releasing ownership"
        );
    }

    #[test]
    fn exec_keeps_mice_owner_and_queue_for_open_fd() {
        use core::sync::atomic::Ordering;
        let _g = MICE_OWNER_LOCK.lock().unwrap();
        reset_mice_state();

        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        let _fd = sys_open(&mut proc, &mut host, b"/dev/input/mice", O_RDONLY, 0).unwrap();
        assert_eq!(
            crate::mouse::MICE_OWNER.load(Ordering::SeqCst),
            proc.pid as i32
        );

        crate::mouse::inject_event(2, 2, 0);
        commit_exec_state(&mut proc, &mut host, 0).unwrap();
        assert_eq!(
            crate::mouse::MICE_OWNER.load(Ordering::SeqCst),
            proc.pid as i32
        );
        assert!(
            crate::mouse::has_data(),
            "exec should retain packets behind a surviving open fd"
        );
        sys_close(&mut proc, &mut host, _fd).unwrap();
    }

    #[test]
    fn exec_keeps_device_state_through_surviving_high_fd_alias() {
        use core::sync::atomic::Ordering;
        let _g = MICE_OWNER_LOCK.lock().unwrap();
        reset_mice_state();

        let mut proc = Process::new(1);
        let mut host = MockHostIO::new();
        sys_setrlimit(&mut proc, 7, 4096, 4096).unwrap();
        let cloexec_fd = sys_open(&mut proc, &mut host, b"/dev/input/mice", O_RDONLY, 0).unwrap();
        proc.fd_table.get_mut(cloexec_fd).unwrap().fd_flags = FD_CLOEXEC;
        let retained_fd = sys_fcntl(&mut proc, cloexec_fd, F_DUPFD, 2048).unwrap();
        assert_eq!(retained_fd, 2048);

        crate::mouse::inject_event(7, -3, 1);
        let pid = proc.pid;
        commit_exec_state(&mut proc, &mut host, pid).unwrap();

        assert!(proc.fd_table.get(cloexec_fd).is_err());
        assert!(proc.fd_table.get(retained_fd).is_ok());
        assert_eq!(
            crate::mouse::MICE_OWNER.load(Ordering::SeqCst),
            proc.pid as i32
        );
        let mut packet = [0u8; 3];
        assert_eq!(
            sys_read(&mut proc, &mut host, retained_fd, &mut packet),
            Ok(3)
        );
        assert_eq!(packet[1] as i8, 7);
        assert_eq!(packet[2] as i8, -3);

        sys_close(&mut proc, &mut host, retained_fd).unwrap();
        assert_eq!(crate::mouse::MICE_OWNER.load(Ordering::SeqCst), -1);
        assert!(!crate::mouse::has_data());
    }

